steps.splice(steps.filter(s=>s.room==='hub').length,0,...fairnessSteps);
// The reasoning engine does not depend on browser state or this module.
steps.push(...branchSteps);
const reasoner=createReasoner(steps,consistencyRules);
export {consistencyRules};
const readingOrder=[];
const appendReading=s=>{readingOrder.push(s);for(const b of steps.filter(x=>x.branch?.after===s.id))appendReading(b);};
steps.filter(s=>!s.branch).forEach(appendReading);
export const stepsIn=(room,answers)=>answers===undefined?readingOrder.filter(s=>s.room===room):reasoner.plan(room,answers);
export const stepById=id=>steps.find(s=>s.id===id);
export const choiceFor=(stepId,choiceId)=>stepById(stepId)?.choices.find(c=>c.id===choiceId);
export const answerState=answers=>reasoner.state(answers);
export const currentChoice=(answers,stepId)=>reasoner.choice(answers,stepId);
export const recordAnswer=(answers,stepId,choiceId,ts_ms)=>reasoner.record(answers,stepId,choiceId,ts_ms);
export function consistencyReview(answers={},resolutions={},room){
 const all=reasoner.checks(answers,resolutions).all.map(c=>({...c,selections:[...c.selections].sort((a,b)=>readingOrder.findIndex(s=>s.id===a.step_id)-readingOrder.findIndex(s=>s.id===b.step_id))})).filter(x=>!room||x.selections.some(a=>stepById(a.step_id).room===room));
 return {all,pending:all.filter(x=>!x.acknowledged),acknowledged:all.filter(x=>x.acknowledged)};
}
export const acknowledgeCheck=(answers,resolutions,id,kind,text,ts_ms)=>reasoner.acknowledge(answers,resolutions,id,kind,text,ts_ms);

// Ledger: for each job, the visitor's current answer (needs / covered / partly / unsure) or nothing yet.
export const ledgerLabels={needs:'Needs objective facts',covered:'Covered by reasons and influences',partly:'Partly',unsure:'Unsure'};
export function ledgerReview(answers={}){
 const current=answerState(answers).current;const rows=jobs.map(j=>{const a=current[j.step],ch=a&&choiceFor(j.step,a.choice_id);return {...j,room:stepById(j.step).room,answer:ch?.ledger||null,label:ch?.label||null};});
 const count=k=>rows.filter(r=>r.answer===k).length;
 return {rows,needs:count('needs'),covered:count('covered'),partly:count('partly'),unsure:count('unsure'),open:count(null)};
}
// What the ledger shows, stated no more strongly than the answers allow. “No job needed objective facts” is said only when every job was answered “covered”.
export function ledgerOutcome(l=ledgerReview()){
 const names=k=>l.rows.filter(r=>r.answer===k).map(r=>r.name),list=xs=>xs.length>1?xs.slice(0,-1).join('; ')+' and '+xs.at(-1):xs[0];
 const kinds=Object.keys(jobKinds).filter(k=>l.rows.some(r=>r.kind===k&&r.answer==='covered')).map(k=>jobKinds[k].toLowerCase());
 if(l.open===l.rows.length)return {verdict:'open',text:''};
 if(l.needs)return {verdict:'narrower',text:`You found ${l.needs===1?'a job':l.needs+' jobs'} that you think needs objective facts: ${list(names('needs'))}. On your reasoning, the exhibit’s claim fails there, and the honest conclusion is narrower.`};
 if(l.covered===l.rows.length)return {verdict:'covered',text:`On your answers, every job was covered without objective facts, across ${kinds.length} kinds of job (${list(kinds)}). That doesn’t show objective facts don’t exist; it shows that, by your reasoning, nothing here depends on them.`};
 const unsettled=[...names('partly'),...names('unsure')];
 return {verdict:'unsettled',text:`No job was answered “needs objective facts”, but that is not the same as showing none does. ${unsettled.length?`You answered partly or unsure on ${unsettled.length===1?'one job':unsettled.length+' jobs'} (${list(unsettled)}); for ${unsettled.length===1?'that job':'those'} the claim is not established. `:''}${l.open?`${l.open===1?'One job is':l.open+' jobs are'} not answered yet.`:''}`.trim()};
}

// Principles: which are held (from the intake or kept by hand), and how a chosen answer bears on them.
export function heldPrinciples(picks={},intake={},released={}){
 const fromIntake=values.filter(p=>p.intake&&intake[p.intake.item]&&(p.intake.when==='agree'?intake[p.intake.item].score>=1:intake[p.intake.item].score<=-1));
 return values.filter(p=>picks[p.id]||(fromIntake.includes(p)&&!released[p.id])).map(p=>({...p,fromIntake:fromIntake.includes(p)}));
}
export function principleNotes(stepId,choiceId,held){
 const key=stepId+'/'+choiceId;
 return held.flatMap(p=>p.fits.includes(key)?[{principle:p,fit:'fits',note:p.fitNote}]:p.strains.includes(key)?[{principle:p,fit:'strains',note:p.strainNote}]:[]);
}
export const principlesFor=(stepId,held)=>held.filter(p=>[...p.fits,...p.strains].some(k=>k.startsWith(stepId+'/')));
export function principleReview(answers={},held=[]){
 const state=answerState(answers);
 return held.map(p=>{const hits=Object.values(state.current).length?Object.entries(state.current).flatMap(([stepId,a])=>{const key=stepId+'/'+a.choice_id,st=stepById(stepId),ch=choiceFor(stepId,a.choice_id);return p.fits.includes(key)?[{fit:'fits',step:st,choice:ch}]:p.strains.includes(key)?[{fit:'strains',step:st,choice:ch}]:[];}):[];return {principle:p,fits:hits.filter(h=>h.fit==='fits'),strains:hits.filter(h=>h.fit==='strains')};});
}
export function intakeComparison(intake={},outtake={},answers={}){
 return intakeItemsList().map(i=>{const a=intake[i.id]?.score,b=outtake[i.id]?.score,side=a>=1?'agree':a<=-1?'disagree':null,p=side&&values.find(v=>v.intake?.item===i.id&&v.intake.when===side),rev=p?principleReview(answers,[p])[0]:null;return {item:i,before:a??null,after:b??null,moved:a!=null&&b!=null?b-a:null,principle:p||null,fits:rev?rev.fits.length:0,strains:rev?rev.strains:[]};});
}
const intakeItemsList=()=>intakeItemsSource;

export function roomReview(room,answers={},resolutions={}){
 const state=answerState(answers),list=stepsIn(room,answers),selected=list.flatMap(step=>{const a=state.current[step.id],choice=choiceFor(step.id,a?.choice_id);return choice?[{step,choice,ts_ms:a.ts_ms}]:[];});
 return {selected,total:list.length,flagged:selected.filter(a=>a.choice.flag),unanswered:list.filter(s=>!state.current[s.id]),stale:state.stale.filter(a=>a.step.room===room),inactive:state.inactive.filter(a=>a.step.room===room),checks:consistencyReview(answers,resolutions,room)};
}
export function journeyReview(answers={},resolutions={}){
 const state=answerState(answers),reviews=rooms.map(r=>roomReview(r.id,answers,resolutions));
 return {answered:Object.keys(state.current).length,total:state.active.length,maximum:steps.length,conditional:steps.filter(s=>s.branch).length,stale:state.stale.map(a=>a.step.id),inactive:state.inactive.map(a=>a.step.id),flagged:reviews.flatMap(r=>r.flagged),checks:consistencyReview(answers,resolutions)};
}
export function exitReview(room,answers={},resolutions={}){
 const r=roomReview(room,answers,resolutions),messages=[];
 if(r.flagged.length)messages.push('One of your answers makes a step that doesn’t follow, or claims more than the evidence shows. The note below explains which.');
 if(r.checks.pending.length)messages.push('Two of your answers pull against each other. You can compare them, explain how they fit, or leave them as they are.');
 if(r.unanswered.length)messages.push(`You haven’t answered ${r.unanswered.length===1?'one question':r.unanswered.length+' questions'} in this room yet. You can come back to them later.`);
 return {...r,needsPrompt:r.flagged.length>0||r.unanswered.length>0||r.checks.pending.length>0,message:messages.join(' ')};
}
const responseRecord=(s,a)=>{const c=choiceFor(s.id,a?.choice_id);return c?{step_id:s.id,room_id:s.room,prompt:s.prompt,choice_id:c.id,label:c.label,feedback:c.feedback,kind:c.kind,flagged:c.flag,...(c.ledger?{ledger:c.ledger}:{}),source_ids:c.sources,ts_ms:a.ts_ms,...(a.basis?{basis:a.basis}:{})}:null;};
export function exportJourney(answers={},overrides=[],ts_ms=Date.now(),resolutions={}){
 if(!Number.isSafeInteger(ts_ms)||ts_ms<0)throw Error('Invalid export timestamp');
 const state=answerState(answers),checks=consistencyReview(answers,resolutions);
 return {ts_ms,edition,kind:'Private record: Morality, Between Us',thesis,responses:readingOrder.flatMap(s=>state.current[s.id]?[responseRecord(s,state.current[s.id])]:[]),inactive_responses:state.inactive.map(({step,answer,reason})=>({...responseRecord(step,answer),status:'inactive',reason})),stale_responses:state.stale.map(({step,answer,reason})=>({...responseRecord(step,answer),status:'needs-reconfirmation',reason})),ledger:ledgerReview(answers).rows.map(r=>({job_id:r.id,step_id:r.step,name:r.name,answer:r.answer})),consistency_checks:checks.all,consistency_resolutions:Object.entries(resolutions).map(([id,r])=>({rule_id:id,...r,current:checks.acknowledged.some(c=>c.id===id&&c.signature===r.signature)})),exit_overrides:overrides.map(o=>({...o})),summary:journeyReview(answers,resolutions),note:'Only current answers count. Answers from an earlier path are kept separately. Explaining how two answers fit records your explanation; it does not score it. Nothing has been submitted.'};
}
